// Package parity holds the cross-flavor parity corpus, the expected results
// generated by each language's real regex runtime, and the helper that engine
// tests call to prove an engine returns exactly what the native runtime does.
package parity

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"reflect"
	"runtime"
	"sort"
	"strings"
	"testing"
	"time"

	"gopkg.in/yaml.v3"

	"github.com/dor1202/lazyregex/internal/engine"
)

// Case is one corpus entry.
type Case struct {
	ID          string   `yaml:"id" json:"id"`
	Flavors     []string `yaml:"flavors" json:"-"`
	Pattern     string   `yaml:"pattern" json:"pattern"`
	Flags       string   `yaml:"flags" json:"flags"`
	Text        string   `yaml:"text" json:"text"`
	Mode        string   `yaml:"mode" json:"mode"`
	Replacement string   `yaml:"replacement" json:"replacement"`
}

// AppliesTo reports whether the case runs for the flavor.
func (c Case) AppliesTo(f engine.Flavor) bool {
	if len(c.Flavors) == 0 {
		return true
	}
	for _, x := range c.Flavors {
		if x == string(f) {
			return true
		}
	}
	return false
}

// Request converts the case to an engine request.
func (c Case) Request() engine.Request {
	return engine.Request{Pattern: c.Pattern, Flags: c.Flags, Text: c.Text, Mode: engine.Mode(c.Mode), Replacement: c.Replacement}
}

// ExpGroup is one capture group in an expected file.
type ExpGroup struct {
	Index   int    `json:"index"`
	Name    string `json:"name"`
	Matched bool   `json:"matched"`
	Span    [2]int `json:"span"`
}

// ExpMatch is one match in an expected file.
type ExpMatch struct {
	Span   [2]int     `json:"span"`
	Groups []ExpGroup `json:"groups"`
}

// Expected is one entry of an expected file.
type Expected struct {
	ID           string     `json:"id"`
	OK           bool       `json:"ok"`
	ErrorMessage string     `json:"error_message,omitempty"`
	Matches      []ExpMatch `json:"matches"`
	Output       *string    `json:"output,omitempty"`
	Parts        []string   `json:"parts,omitempty"`
	PartsNil     []bool     `json:"parts_nil,omitempty"`
	Unit         string     `json:"unit"`
}

// Normalize puts an entry into canonical form so generator output from
// different languages (and the engine's own result) compare and serialize alike.
func (x *Expected) Normalize() {
	if !x.OK {
		x.Unit, x.Output, x.Parts, x.PartsNil, x.Matches = "", nil, nil, nil, nil
	}
	if x.Matches == nil {
		x.Matches = []ExpMatch{}
	}
	for i := range x.Matches {
		if x.Matches[i].Groups == nil {
			x.Matches[i].Groups = []ExpGroup{}
		}
		for j := range x.Matches[i].Groups {
			if g := &x.Matches[i].Groups[j]; !g.Matched {
				g.Span = [2]int{-1, -1}
			}
		}
	}
	any := false
	for _, b := range x.PartsNil {
		any = any || b
	}
	if !any {
		x.PartsNil = nil
	}
	if len(x.Parts) == 0 {
		x.Parts = nil
	}
}

// UnitName is the string used for an engine.Unit in expected files.
func UnitName(u engine.Unit) string {
	switch u {
	case engine.UnitCodePoints:
		return "codepoints"
	case engine.UnitUTF16:
		return "utf16"
	}
	return "bytes"
}

// Dir returns the absolute path of the parity directory.
func Dir() string {
	_, file, _, ok := runtime.Caller(0)
	if !ok {
		panic("parity: cannot locate source directory")
	}
	return filepath.Dir(file)
}

// LoadCorpus loads every corpus file, keyed by corpus name (file name without extension).
func LoadCorpus(dir string) (map[string][]Case, error) {
	files, err := filepath.Glob(filepath.Join(dir, "*.yaml"))
	if err != nil {
		return nil, err
	}
	out := map[string][]Case{}
	seen := map[string]string{}
	for _, f := range files {
		b, err := os.ReadFile(f)
		if err != nil {
			return nil, err
		}
		var cases []Case
		if err := yaml.Unmarshal(b, &cases); err != nil {
			return nil, fmt.Errorf("%s: %w", f, err)
		}
		name := strings.TrimSuffix(filepath.Base(f), ".yaml")
		for i := range cases {
			c := &cases[i]
			if c.ID == "" {
				return nil, fmt.Errorf("%s: case %d has no id", f, i)
			}
			if prev, dup := seen[c.ID]; dup {
				return nil, fmt.Errorf("duplicate case id %q in %s and %s", c.ID, prev, name)
			}
			seen[c.ID] = name
			if c.Mode == "" {
				c.Mode = string(engine.ModeMatch)
			}
		}
		out[name] = cases
	}
	return out, nil
}

// Exception waives one compared field of one case for one flavor.
type Exception struct {
	Flavor string `yaml:"flavor"`
	ID     string `yaml:"id"`
	Field  string `yaml:"field"`
	Reason string `yaml:"reason"`
}

// LoadExceptions reads exceptions.yaml.
func LoadExceptions(path string) ([]Exception, error) {
	b, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	var ex []Exception
	if err := yaml.Unmarshal(b, &ex); err != nil {
		return nil, fmt.Errorf("%s: %w", path, err)
	}
	return ex, nil
}

// Evaluate runs a case on an engine and converts the outcome to an Expected.
// Errors other than *engine.CompileError are returned.
func Evaluate(ctx context.Context, e engine.Engine, c Case) (Expected, error) {
	res, err := e.Eval(ctx, c.Request())
	x := Expected{ID: c.ID, OK: true, Unit: UnitName(res.Unit)}
	if err != nil {
		var ce *engine.CompileError
		if !errors.As(err, &ce) {
			return x, err
		}
		x.OK = false
		x.ErrorMessage = ce.Message
		x.Unit = ""
		x.Normalize()
		return x, nil
	}
	for _, m := range res.Matches {
		em := ExpMatch{Span: [2]int{m.Span.Start, m.Span.End}}
		for _, g := range m.Groups {
			em.Groups = append(em.Groups, ExpGroup{Index: g.Index, Name: g.Name, Matched: g.Matched, Span: [2]int{g.Span.Start, g.Span.End}})
		}
		x.Matches = append(x.Matches, em)
	}
	switch engine.Mode(c.Mode) {
	case engine.ModeReplace:
		out := res.Output
		x.Output = &out
	case engine.ModeSplit:
		x.Parts = res.Parts
		x.PartsNil = res.PartsNil
	}
	x.Normalize()
	return x, nil
}

// jsonRoundTrip makes an engine-produced entry look like a decoded file entry
// (invalid UTF-8 becomes U+FFFD exactly as it does when a fixture is written).
func jsonRoundTrip(x Expected) (Expected, error) {
	b, err := json.Marshal(x)
	if err != nil {
		return x, err
	}
	var y Expected
	if err := json.Unmarshal(b, &y); err != nil {
		return x, err
	}
	y.Normalize()
	return y, nil
}

// Diff compares want (native) with got (engine) and returns, per field, a
// description of the difference. Fields: error_message, matches, output, parts, unit.
func Diff(want, got Expected) map[string]string {
	d := map[string]string{}
	show := func(v any) string { b, _ := json.Marshal(v); return string(b) }
	if want.OK != got.OK || want.ErrorMessage != got.ErrorMessage {
		d["error_message"] = fmt.Sprintf("want ok=%v %q, got ok=%v %q", want.OK, want.ErrorMessage, got.OK, got.ErrorMessage)
		return d
	}
	if !want.OK {
		return d
	}
	if !reflect.DeepEqual(want.Matches, got.Matches) {
		d["matches"] = fmt.Sprintf("want %s\n got %s", show(want.Matches), show(got.Matches))
	}
	if !reflect.DeepEqual(want.Output, got.Output) {
		d["output"] = fmt.Sprintf("want %s\n got %s", show(want.Output), show(got.Output))
	}
	if !reflect.DeepEqual(want.Parts, got.Parts) || !reflect.DeepEqual(want.PartsNil, got.PartsNil) {
		d["parts"] = fmt.Sprintf("want %s nil=%s\n got %s nil=%s", show(want.Parts), show(want.PartsNil), show(got.Parts), show(got.PartsNil))
	}
	if want.Unit != got.Unit {
		d["unit"] = fmt.Sprintf("want %s, got %s", want.Unit, got.Unit)
	}
	return d
}

// RunParity checks engine e against parity/expected/<flavor>/*.json: every
// corpus case that applies to the flavor must have an expected entry, and the
// engine's result must equal it field by field, except for fields listed in
// parity/exceptions.yaml.
func RunParity(t *testing.T, flavor engine.Flavor, e engine.Engine) {
	t.Helper()
	root := Dir()
	corpus, err := LoadCorpus(filepath.Join(root, "corpus"))
	if err != nil {
		t.Fatal(err)
	}
	exceptions, err := LoadExceptions(filepath.Join(root, "exceptions.yaml"))
	if err != nil {
		t.Fatal(err)
	}
	waived := map[string]string{}
	for _, x := range exceptions {
		if x.Flavor == string(flavor) {
			waived[x.ID+"\x00"+x.Field] = x.Reason
		}
	}
	expDir := filepath.Join(root, "expected", string(flavor))
	if _, err := os.Stat(expDir); err != nil {
		t.Fatalf("no expected fixtures for %s: %v (generate with: make parity-gen FLAVOR=%s)", flavor, err, flavor)
	}

	names := make([]string, 0, len(corpus))
	for n := range corpus {
		names = append(names, n)
	}
	sort.Strings(names)
	total := 0
	for _, name := range names {
		var applicable []Case
		for _, c := range corpus[name] {
			if c.AppliesTo(flavor) {
				applicable = append(applicable, c)
			}
		}
		if len(applicable) == 0 {
			continue
		}
		b, err := os.ReadFile(filepath.Join(expDir, name+".json"))
		if err != nil {
			t.Errorf("%s: missing fixture for corpus %q: %v", flavor, name, err)
			continue
		}
		var exp []Expected
		if err := json.Unmarshal(b, &exp); err != nil {
			t.Errorf("%s/%s.json: %v", flavor, name, err)
			continue
		}
		byID := map[string]Expected{}
		for _, x := range exp {
			x.Normalize()
			byID[x.ID] = x
		}
		inCorpus := map[string]bool{}
		for _, c := range applicable {
			inCorpus[c.ID] = true
			want, ok := byID[c.ID]
			if !ok {
				t.Errorf("%s/%s.json: no expected entry for case %q (stale fixtures)", flavor, name, c.ID)
				continue
			}
			total++
			t.Run(c.ID, func(t *testing.T) {
				ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
				defer cancel()
				got, err := Evaluate(ctx, e, c)
				if err != nil {
					t.Fatalf("case %s: %v", c.ID, err)
				}
				if got, err = jsonRoundTrip(got); err != nil {
					t.Fatalf("case %s: %v", c.ID, err)
				}
				fields := Diff(want, got)
				keys := make([]string, 0, len(fields))
				for k := range fields {
					keys = append(keys, k)
				}
				sort.Strings(keys)
				for _, field := range keys {
					if reason, ok := waived[c.ID+"\x00"+field]; ok {
						t.Logf("case %s: %s differs but is waived (%s): %s", c.ID, field, reason, fields[field])
						continue
					}
					t.Errorf("case %s: %s mismatch (pattern %q flags %q text %q)\n%s", c.ID, field, c.Pattern, c.Flags, c.Text, fields[field])
				}
			})
		}
		for _, x := range exp {
			if !inCorpus[x.ID] {
				t.Errorf("%s/%s.json: entry %q is not in the corpus for this flavor (stale fixtures)", flavor, name, x.ID)
			}
		}
	}
	if total == 0 {
		t.Errorf("no parity cases ran for %s", flavor)
	}
}
